// migratedCheckpointTree returns the tree to store under the checkpoint's ref:
// the branch subtree with its root metadata.json normalized for the git-refs
// layout. The subtree is returned unchanged when the metadata is already
// normalized or absent.
func migratedCheckpointTree(ctx context.Context, repo *git.Repository, cid id.CheckpointID, cpTreeHash plumbing.Hash) (plumbing.Hash, error) {
	subtree, err := repo.TreeObject(cpTreeHash)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("read checkpoint tree: %w", err)
	}
	metadataFile, err := subtree.File(paths.MetadataFileName)
	if err != nil {
		if errors.Is(err, object.ErrFileNotFound) {
			return cpTreeHash, nil
		}
		return plumbing.ZeroHash, fmt.Errorf("read metadata.json: %w", err)
	}
	raw, err := metadataFile.Contents()
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("read metadata.json: %w", err)
	}

	normalized, changed, err := normalizeMigratedMetadata([]byte(raw), cid)
	if err != nil {
		return plumbing.ZeroHash, err
	}
	if !changed {
		return cpTreeHash, nil
	}

	blobHash, err := CreateBlobFromContent(repo, normalized)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("write normalized metadata.json: %w", err)
	}
	entries := make(map[string]object.TreeEntry)
	if err := FlattenTree(repo, subtree, "", entries); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("flatten checkpoint tree: %w", err)
	}
	entries[paths.MetadataFileName] = object.TreeEntry{Name: paths.MetadataFileName, Mode: filemode.Regular, Hash: blobHash}
	newTree, err := BuildTreeFromEntries(ctx, repo, entries)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("build normalized checkpoint tree: %w", err)
	}
	return newTree, nil
}

// sessionPathFields are the SessionFilePaths members holding tree-root-relative
// paths that need rebasing when a checkpoint moves from the sharded branch
// layout to its own ref.
var sessionPathFields = []string{"metadata", "transcript", "compact_transcript", "content_hash", "prompt"}

// normalizeMigratedMetadata rewrites a checkpoint's root metadata.json for the
// git-refs layout: the legacy checkpoint_version field (stamped "branch-v1" by
// older CLIs) is dropped, and sessions[] paths lose the "/<shard>/<id>" prefix
// so they resolve against the ref's own tree root like native git-refs writes.
// The raw JSON object is edited in place — not round-tripped through
// CheckpointSummary — so fields this CLI version doesn't model are preserved.
// Returns changed=false when the metadata already matches the refs layout.
func normalizeMigratedMetadata(raw []byte, cid id.CheckpointID) (normalized []byte, changed bool, err error) {
	var doc map[string]any
	if err := json.Unmarshal(raw, &doc); err != nil {
		return nil, false, fmt.Errorf("parse metadata.json: %w", err)
	}

	if _, ok := doc["checkpoint_version"]; ok {
		delete(doc, "checkpoint_version")
		changed = true
	}

	branchPrefix := "/" + cid.Path()
	sessions, _ := doc["sessions"].([]any)
	for _, entry := range sessions {
		session, ok := entry.(map[string]any)
		if !ok {
			continue
		}
		for _, field := range sessionPathFields {
			value, ok := session[field].(string)
			if !ok {
				continue
			}
			if rest, found := strings.CutPrefix(value, branchPrefix); found && strings.HasPrefix(rest, "/") {
				session[field] = rest
				changed = true
			}
		}
	}
	if !changed {
		return nil, false, nil
	}

	normalized, err = jsonutil.MarshalIndentWithNewline(doc, "", "  ")
	if err != nil {
		return nil, false, fmt.Errorf("encode metadata.json: %w", err)
	}
	return normalized, true, nil
}

