56	func (q *PushQueue) lockPath() string  { return filepath.Join(q.dir, pushQueueLockName) }
57	
58	// Enqueue appends a ref to the queue. It is safe to enqueue a ref already
59	// present (or already pushed): Drain collapses duplicates and the batch push is
60	// idempotent. Enqueue takes the lock so concurrent writers never interleave a
61	// partial line.
62	func (q *PushQueue) Enqueue(ref plumbing.ReferenceName) error {
63		release, err := flock.Acquire(q.lockPath())
64		if err != nil {
65			return fmt.Errorf("lock push queue: %w", err)
66		}
67		defer release()
68	
69		line, err := json.Marshal(pushQueueEntry{Ref: ref.String()})
70		if err != nil {
71			return fmt.Errorf("encode push queue entry: %w", err)
72		}
73		f, err := os.OpenFile(q.queuePath(), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o600)
74		if err != nil {
75			return fmt.Errorf("open push queue: %w", err)
76		}
77		defer f.Close()
78		if _, err := f.Write(append(line, '\n')); err != nil {
79			return fmt.Errorf("append push queue entry: %w", err)
80		}
81		return nil
82	}
83	
84	// Drain returns the de-duplicated refs currently queued, in first-seen order. It
85	// does NOT remove them; call Remove after a confirmed push so a failed push
86	// retries next time. A missing queue file yields no refs.
87	//
88	// It compacts the file in place: when the on-disk queue held redundant lines
89	// (duplicate enqueues of the same ref, or malformed/blank lines), Drain rewrites
90	// it to the de-duplicated set. Enqueue only ever appends, so without this the
91	// file would grow unboundedly between the Removes that are otherwise the sole
92	// compaction point (e.g. a long-lived session that keeps re-enqueuing the same
93	// checkpoint ref but never pushes).
94	func (q *PushQueue) Drain() ([]plumbing.ReferenceName, error) {
95		release, err := flock.Acquire(q.lockPath())
96		if err != nil {
97			return nil, fmt.Errorf("lock push queue: %w", err)
98		}
99		defer release()
100	
101		refs, rawLines, err := q.readLocked()
102		if err != nil {
103			return nil, err
104		}
105		if rawLines > len(refs) {
106			if err := q.rewriteLocked(refs); err != nil {
107				return nil, err
108			}
109		}
110		return refs, nil
111	}
